    /* A functional which takes a single parameter of a parametric type
     * bound by Any cannot be overloaded.
     */
    private def checkBoundAny(param: Type, sparams: List[StaticParam]): Boolean =
      if (param.isInstanceOf[VarType]) {
        val tyName = param.asInstanceOf[VarType].getName.getText
        sparams.exists(sp =>

        sparams.exists(sp =>
                       sp.getName.getText.equals(tyName) &&
                       toList(sp.getExtendsClause).exists(_.isInstanceOf[AnyType]))
      } else false

    /* A pair's validity depends on its two signatures as instantiated where it is checked,
     * on the other signatures there, on whether they are dotted methods and on the static
     * parameters in scope, so a valid answer is reused only where all of these are equal. */
    private var staticParamsInScope: List[StaticParam] = Nil
    private val validOverloadingMemo = new scala.collection.mutable.HashMap[
        (ArrowType, Option[Int], ArrowType, Option[Int], Set[(ArrowType, Option[Int])], Boolean, List[StaticParam]), Boolean]()

    private def validOverloading(first: (ArrowType,Option[Int],Option[JavaFunctional]),
				 second: (ArrowType,Option[Int],Option[JavaFunctional]),
				 signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
				 isMethod: Boolean,
				 oa: OverloadingOracle,
				 debug:Boolean=false): Boolean = {
        val fnal1 = first._3
        val fnal2 = second._3
        if (cacheOverloadChecks && !fnal1.isEmpty && !fnal2.isEmpty) {
            val key = (first._1, first._2, second._1, second._2,
                       signatures.map(s => (s._1, s._2)).toSet, isMethod, staticParamsInScope)
            val cv = validOverloadingMemo.get(key)
            if (!cv.isEmpty && cv.get)
	        true
	    else {
                val result = validOverloadingInner(first, second, signatures, isMethod, oa, debug)
                if (result) validOverloadingMemo += (key -> result)
                result
            }
        } else validOverloadingInner(first, second, signatures, isMethod, oa, debug)
    }

    /* Checks the overloading rules: subtype / exclusion / meet */
    private def validOverloadingInner(first: (ArrowType,Option[Int],Option[JavaFunctional]),
				      second: (ArrowType,Option[Int],Option[JavaFunctional]),
				      signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
				      isMethod: Boolean,
				      oa: OverloadingOracle,
				      debug:Boolean=false): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      true

      if (oa.lteq(fa, ga)) { true }
      else if (oa.lteq(ga, fa)) { true }
      else if (functionalMethodsAtOnePosition(first, second, isMethod)) { true }
      else if (meetRule(first, second, signatures, isMethod, oa, debug)) { true }
      else if (oa.excludes(fa, ga)) { true }
      else { coverageRule(first, second, signatures, isMethod, oa) }


  /*    
      println("Specificity\n")
      val b1 = oa.lteq(fa, ga)
      if (b1) true 
      val b2 = oa.lteq(ga, fa) 
      if (b2) return true
      println("Meet Rule\n")
      val b3 = meetRule(first, second, signatures, isMethod, oa, debug)
      if (b3) return true
      println("Exclusion\n")
      val b4 = oa.excludes(fa, ga) 
      println("Done")
      return b4
  */

      //if (b1) !b2 else ( b2 || b3 || b4 )  //JT: It looks like the duplicate rule IS enforced somewhere else
      //(b1 || b2 || b3 || b4)
    }

    /* The Meet Rule for Functional Methods: two functional methods with their self
     * parameters at one position are a valid overloading among the top-level functionals;
     * the meet the rule asks of a trait or object that provides both is checked for that
     * trait or object (checkOverloading's loop over them). */
    private def functionalMethodsAtOnePosition(first: (ArrowType,Option[Int],Option[JavaFunctional]),
                                               second: (ArrowType,Option[Int],Option[JavaFunctional]),
                                               isMethod: Boolean): Boolean =
      !isMethod && first._2.isDefined && first._2 == second._2 &&
      first._3.exists(isFunctionalMethod) && second._3.exists(isFunctionalMethod)

    private def meetRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
    	                 second: (ArrowType,Option[Int],Option[JavaFunctional]),
			 signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			 isMethod: Boolean,
			 oa: OverloadingOracle,
			 debug : Boolean = false): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      val b1 = fsp == gsp
      val b2 = (fsp == gsp) &&
      signatures.exists(third => third match {
           case (ha, hsp, _) => {
              val a1 = (hsp == fsp) 
              val a2 = a1 && oa.lteq(ha, fa) 
              val a3 = a2 && oa.lteq(ha, ga) 
              val a4 = a3 && (if (isMethod && fsp.isDefined)
                                oa.isMeet(withoutSelf(ha, fsp.get), withoutSelf(fa, fsp.get), withoutSelf(ga, fsp.get), false, debug)
                              else oa.isMeet(ha, fa, ga, isMethod, debug))
     //         if (debug)
     //             println("" + ha + " " + a1 + a2 + a3 + a4)

              a4}})
      b2
    }

    // the self parameter of a functional method is compared as a dotted method's receiver is, wherever it sits
    private def withoutSelf(a: ArrowType, i: Int): ArrowType = {
      val d = a.getDomain match {
        case t: TupleType =>
          NF.makeTupleType(NU.getSpan(t), toJavaList(toListFromImmutable(t.getElements).zipWithIndex.filter(_._2 != i).map(_._1)))
        case t => NF.makeTupleType(NU.getSpan(t), toJavaList(List[Type]()))
      }
      NF.makeArrowType(NU.getSpan(a), d, a.getRange, a.getInfo.getStaticParams)
    }

    /* The Meet Rule's closed-trait case, for functions and functional methods: the
     * declarations whose domains are below both domains together hold every value of
     * their overlap, as the comprises clauses show (OverloadingOracle.coversOverlap). */
    private def coverageRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
                             second: (ArrowType,Option[Int],Option[JavaFunctional]),
                             signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
                             isMethod: Boolean,
                             oa: OverloadingOracle): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      if (fsp != gsp || (isMethod && fsp.isEmpty)) false
      else oa.coversOverlap(fa, ga, signatures.collect {
        case (ha, hsp, _) if hsp == fsp && !(ha eq fa) && !(ha eq ga) &&
                             oa.lteq(ha, fa) && oa.lteq(ha, ga) => ha })
    }

    private def returnTypeCheck(name: IdOrOpOrAnonymousName,
    	    			first: (ArrowType,Option[Int],Option[JavaFunctional]),
                                second: (ArrowType,Option[Int],Option[JavaFunctional]),
			        oa: OverloadingOracle) = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
//          println("Satisfies return type rule?\n   " + typeAndSpanToString(fa) + "\n   " + typeAndSpanToString(ga))
      if (!oa.satisfiesReturnTypeRule(fa, ga)) {
//        println("For " + name + ",\nthe return type of " + typeAndSpanToString(fa) + " should be a subtype of the\n    return type of " + typeAndSpanToString(ga))
        error(mergeSpan(fa, ga),
	      "For " + name + ",\nthe return type of " + typeAndSpanToString(fa) + " should be a subtype of the\n    return type of " + typeAndSpanToString(ga))
      }
      else if (oa.lteq(fa, ga) && !oa.satisfiesPositionalRule(fa, ga))
        error(mergeSpan(fa, ga),
              "For " + name + ",\nthe static parameters of " + typeAndSpanToString(fa) + " should correspond position by position\n    to those of " + typeAndSpanToString(ga) +
              ":\n    of the same kinds, with a return type that is a subtype of the other's under that correspondence.")
    }


    /* Drop the first element denoting the receiver type of the given type. */
    private def dropReceiver(param: Type) = param match {
      case STupleType(info, _::ty::Nil, None, Nil) => ty
      case STupleType(info, elements, varargs, keywords) =>
        STupleType(info, elements.takeRight(elements.size-1), varargs, keywords)
      case _ => NodeFactory.makeVoidType(NU.getSpan(param))
    }

    def isDeclaredName(f: IdOrOpOrAnonymousName) = f match {
        case SId(_,_,str) => IdentifierUtil.validId(str)
        case SOp(_,_,str,_,_) => NU.validOp(str)
        case _ => false
    }

    def isDeclaredMethod(f: JavaFunctional) = f match {
        case SDeclaredMethod(_,_) => true
        case _ => false
    }

    def isFunction(f: JavaFunctional) = f match {
        case SDeclaredFunction(_) => true
        case SFunctionalMethod(_,_) => true
        case SConstructor(_,_,_,_,_) => true
        case _ => false
    }

    def isFunctionalMethod(f: JavaFunctional) = f match {
        case SFunctionalMethod(_,_) => true
        case _ => false
    }

    def isDeclaredVariable(v: JavaVariable) = v match {
        case SDeclaredVariable(_) => true
        case _ => false
    }

    private def mergeSpan(first: ArrowType, second: ArrowType): Span = mergeSpan(NU.getSpan(first), NU.getSpan(second))

    private def mergeSpan(first: Span, second: Span): Span = new MultiSpan(first, second)

    /* Returns the type of the given list of parameters. */
    private def paramsToType(params: JavaList[Param], span: Span): Type =
      STypesUtil.paramsToType(toListFromImmutable(params), span) match {
        case Some(ty) => ty
        case _ =>
          val span = NU.spanAll(params)
          error(span,
                "Type checking couldn't infer the type of " + params)
          NodeFactory.makeVoidType(span)
      }

    /* Returns the type of the given self type and a list of parameters. */
    private def paramsToType(self: Type, params: JavaList[Param], span: Span): Type = {
      val span = params.size match {
        case 0 => NU.getSpan(self)
        case _ => NU.spanAll(params)
      }
      val elems = toListFromImmutable(params).map(paramToType)
      if (elems.forall(_.isDefined))
        NodeFactory.makeTupleTypeOrType(span, toJavaList(List(self) ++ elems.map(_.get)))
      else {
        error(span,
              "Type checking couldn't infer the type of " + params)
        NodeFactory.makeVoidType(span)
      }
    }

    private def error(loc: Span, msg: String) =
        errors = errors ::: List(TypeError.make(msg, loc))


    // The following is used by the ExportChecker.

    def coverOverloading(set: Set[JavaFunction]) = {
      var result = Set[JavaFunction]()
      for (f <- set ; if !coveredBy(f, set)) {
        result = result + f
      }
      result = result.filter {
